//! Parity and regression tests for the chatterbox_turbo family.
//!
//! Pinned fixtures reside in `testdata/tts_chatterbox_turbo/`,
//! generated by `tools/gen_chatterbox_turbo_fixtures.py` against
//! mlx-audio commit `e1b19b9054bf163f5d812221a54fcc346f1890e9`
//! (mlx 0.32.3) on the CPU device. The generator runs the true
//! reference modules at tiny seeded geometry (a 2-layer GPT-2-32
//! backbone rides the patched reference `create_gpt2_config` /
//! `GPT2_MEDIUM_CONFIG`; the flow, HiFT, CAMPPlus, voice encoder, and
//! S3 tokenizer all run reference code at shrunk widths), so the
//! traces carry the conditioning rows, the greedy and sampled T3
//! streams with per-step head logits, the meanflow mel, the HiFT
//! waveform with recorded sine draws, the end-to-end generate
//! realization, the Kaldi fbank + CAMPPlus embedding, and the sampler
//! math on fixed logits. Every case was replayed on the Python side
//! before freezing (same weights, same streams, bitwise-identical).

use std::path::{Path, PathBuf};

use serde_json::Value;

use super::flow::FlowNoise;
use super::hift::SineDraws;
use super::{punc_norm, GenerateParams, Model, ModelConfig, S3GEN_SIL, SPEECH_VOCAB_SIZE};
use crate::music::minimax_music3::rng;
use crate::tts::chatterbox_turbo::t3::{
    apply_repetition_penalty, apply_top_k_threshold, apply_top_p_shift,
};

fn testdata(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/tts_chatterbox_turbo")
        .join(name)
}

fn read_json(path: &Path) -> Value {
    let text = std::fs::read_to_string(path).expect("fixture json");
    serde_json::from_str(&text).expect("fixture json")
}

fn f32_vec(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("values")
        .iter()
        .map(|v| v.as_f64().expect("value") as f32)
        .collect()
}

/// Reads a float vector where non-finite entries carry `null` (JSON has
/// no infinity); `null` maps back to -inf.
fn f32_vec_masked(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("values")
        .iter()
        .map(|v| v.as_f64().map(|x| x as f32).unwrap_or(f32::NEG_INFINITY))
        .collect()
}

fn i32_vec(value: &Value) -> Vec<i32> {
    value
        .as_array()
        .expect("ids")
        .iter()
        .map(|v| v.as_i64().expect("id") as i32)
        .collect()
}

/// Reads a float32 `.npy` into (shape, data).
fn read_npy(path: &Path) -> (Vec<usize>, Vec<f32>) {
    let bytes = std::fs::read(path).expect("npy file");
    assert_eq!(&bytes[..6], b"\x93NUMPY");
    let header_len = u16::from_le_bytes([bytes[8], bytes[9]]) as usize;
    let header = std::str::from_utf8(&bytes[10..10 + header_len]).unwrap();
    let start = header.find('(').unwrap() + 1;
    let end = header[start..].find(')').unwrap() + start;
    let shape: Vec<usize> = header[start..end]
        .split(',')
        .filter_map(|p| p.trim().parse::<usize>().ok())
        .collect();
    let data = bytes[10 + header_len..]
        .chunks_exact(4)
        .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect();
    (shape, data)
}

/// Reads an int32 `.npy` into (shape, data).
fn read_npy_i32(path: &Path) -> (Vec<usize>, Vec<i32>) {
    let bytes = std::fs::read(path).expect("npy file");
    assert_eq!(&bytes[..6], b"\x93NUMPY");
    let header_len = u16::from_le_bytes([bytes[8], bytes[9]]) as usize;
    let header = std::str::from_utf8(&bytes[10..10 + header_len]).unwrap();
    let start = header.find('(').unwrap() + 1;
    let end = header[start..].find(')').unwrap() + start;
    let shape: Vec<usize> = header[start..end]
        .split(',')
        .filter_map(|p| p.trim().parse::<usize>().ok())
        .collect();
    let data = bytes[10 + header_len..]
        .chunks_exact(4)
        .map(|c| i32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect();
    (shape, data)
}

fn max_diff(a: &[f32], b: &[f32]) -> f32 {
    assert_eq!(
        a.len(),
        b.len(),
        "length mismatch: {} vs {}",
        a.len(),
        b.len()
    );
    a.iter()
        .zip(b)
        .map(|(x, y)| (x - y).abs())
        .fold(0.0f32, f32::max)
}

/// Opens the tiny fixture model with its S3 tokenizer.
fn open_model() -> Model {
    Model::open(&testdata("")).expect("opens the fixture model")
}

/// The fixture T3 conditioning (`t3/traces.json`).
fn t3_cond_from_traces(traces: &Value) -> super::t3::T3Cond {
    super::t3::T3Cond {
        speaker_emb: f32_vec(&traces["speaker_emb"]),
        cond_prompt_speech_tokens: Some(i32_vec(&traces["cond_prompt_speech_tokens"])),
    }
}

fn turbo_t3_params(temperature: f32) -> super::t3::T3GenParams {
    super::t3::T3GenParams {
        max_gen_len: 12,
        temperature,
        top_k: 1000,
        top_p: 0.95,
        repetition_penalty: 1.2,
    }
}

/// The flow-case reference inputs.
struct FlowInputs {
    prompt_tokens: Vec<i32>,
    gen_tokens: Vec<i32>,
    prompt_feat: Vec<f32>,
    embedding: Vec<f32>,
    noised_mels: Vec<f32>,
    z_prompt: Vec<f32>,
    flow_mel: Vec<f32>,
}

fn flow_inputs() -> FlowInputs {
    let (_, prompt_tokens) = read_npy_i32(&testdata("flow/prompt_tokens.npy"));
    let (_, gen_tokens) = read_npy_i32(&testdata("flow/gen_tokens.npy"));
    let (_, prompt_feat) = read_npy(&testdata("flow/prompt_feat.npy"));
    let (_, embedding) = read_npy(&testdata("flow/embedding.npy"));
    let (_, noised_mels) = read_npy(&testdata("flow/noised_mels.npy"));
    let (_, z_prompt) = read_npy(&testdata("flow/z_prompt.npy"));
    let (_, flow_mel) = read_npy(&testdata("flow/flow_mel.npy"));
    FlowInputs {
        prompt_tokens,
        gen_tokens,
        prompt_feat,
        embedding,
        noised_mels,
        z_prompt,
        flow_mel,
    }
}

fn flow_noise(inputs: &FlowInputs) -> FlowNoise {
    FlowNoise {
        gen_window: inputs.noised_mels.clone(),
        prompt_window: inputs.z_prompt.clone(),
    }
}

#[test]
fn config_matches_reference_defaults() {
    let value = read_json(&testdata("config.json"));
    let config = ModelConfig::from_json(&value).unwrap();
    // T3 specials are the pinned reference tokens.
    assert_eq!(config.t3.start_text_token, 255);
    assert_eq!(config.t3.stop_text_token, 0);
    assert_eq!(config.t3.start_speech_token, 6561);
    assert_eq!(config.t3.stop_speech_token, 6562);
    assert_eq!(config.t3.speech_tokens_dict_size, 6563);
    assert_eq!(config.t3.text_tokens_dict_size, 64);
    assert_eq!(config.t3.speech_cond_prompt_len, 375);
    assert_eq!(config.t3.speaker_embed_size, 256);
    // Turbo drops the sibling family's perceiver and emotion scalar.
    assert!(!config.t3.use_perceiver_resampler);
    assert!(!config.t3.emotion_adv);
    // The gpt2 backbone config parses through the shared module.
    assert_eq!(config.t3.gpt2["model_type"], "gpt2");
    assert_eq!(config.t3.gpt2["n_layer"], 2);
    // Conditioning lengths: 15 s at 16 kHz, 10 s at 24 kHz.
    assert_eq!(config.s3_sr, 16000);
    assert_eq!(config.s3gen_sr, 24000);
    assert_eq!(config.enc_cond_len, 15 * 16000);
    assert_eq!(config.dec_cond_len, 10 * 24000);
    // Flow defaults survive parsing: the fixture overrides a subset.
    let defaults = ModelConfig::default();
    assert!(config.flow.meanflow);
    assert_eq!(config.flow.n_timesteps, 2);
    assert_eq!(
        config.flow.inference_cfg_rate,
        defaults.flow.inference_cfg_rate
    );
    assert_eq!(config.flow.output_size, 80);
    assert_eq!(config.flow.upsample_stride, 2);
    assert_eq!(config.hift.base_channels, 64);
    // The untouched defaults parse to the reference geometry.
    let parsed = ModelConfig::from_json(&serde_json::json!({})).unwrap();
    assert_eq!(parsed.t3.text_tokens_dict_size, 50276);
    assert_eq!(parsed.t3.gpt2["n_embd"], 1024);
    assert_eq!(parsed.enc_cond_len, 15 * 16000);
    assert_eq!(parsed.flow.decoder_num_mid_blocks, 12);
}

#[test]
fn conditioning_rows_match_reference() {
    let traces = read_json(&testdata("t3/traces.json"));
    let model = open_model();
    let cond = t3_cond_from_traces(&traces);
    let cond_rows = model.t3.prepare_conditioning(&cond).unwrap();
    let expected = f32_vec(&traces["cond_rows"]);
    let diff = max_diff(&cond_rows, &expected);
    assert!(diff < 2e-4, "conditioning rows difference {diff}");
    // The composite prompt embeds: [cond | text | start_speech].
    let text_ids = i32_vec(&traces["text_ids"]);
    let prompt = model.prepare_text_tokens(&text_ids);
    let embeds = model.t3.prepare_input_embeds(&cond_rows, &prompt).unwrap();
    let expected = f32_vec(&traces["prompt_embeds"]);
    let diff = max_diff(&embeds, &expected);
    assert!(diff < 2e-4, "prompt embeds difference {diff}");
}

#[test]
fn t3_greedy_generation_matches_reference() {
    let traces = read_json(&testdata("t3/traces.json"));
    let mut model = open_model();
    let cond = t3_cond_from_traces(&traces);
    let text_ids = i32_vec(&traces["text_ids"]);
    let prompt = model.prepare_text_tokens(&text_ids);
    let mut keys = rng::KeySequence::new(0);
    let ids = model
        .t3
        .inference_turbo(&cond, &prompt, &turbo_t3_params(0.0), &mut keys)
        .unwrap();
    let expected = i32_vec(&traces["greedy_ids"]);
    assert_eq!(ids, expected, "greedy id stream diverged");

    // The per-step decision inputs: the repetition penalty over the
    // recorded head calls; the per-step argmax must reproduce the
    // chosen ids and the recorded decision margins.
    let (_, head_calls) = read_npy(&testdata("t3/greedy_head_calls.npy"));
    let steps = expected.len();
    let vocab = head_calls.len() / steps;
    assert_eq!(vocab, model.config.t3.speech_tokens_dict_size);
    let margins = traces["greedy_margins"].as_array().unwrap();
    for step in 0..steps {
        let call = &head_calls[step * vocab..(step + 1) * vocab];
        let mut penalized = call.to_vec();
        let context: Vec<i32> = expected[..step].to_vec();
        apply_repetition_penalty(&mut penalized, &context, 1.2);
        let top = crate::tts::sampling::argmax(&penalized);
        assert_eq!(
            top, expected[step] as usize,
            "greedy argmax diverged at step {step}"
        );
        let mut sorted = penalized.clone();
        sorted.sort_by(|a, b| b.partial_cmp(a).unwrap());
        let diff = (sorted[0] - sorted[1] - margins[step].as_f64().unwrap() as f32).abs();
        assert!(diff < 1e-4, "greedy margin {diff} at step {step}");
    }
}

#[test]
fn t3_sampled_generation_matches_reference() {
    let traces = read_json(&testdata("t3/traces.json"));
    let mut model = open_model();
    let cond = t3_cond_from_traces(&traces);
    let text_ids = i32_vec(&traces["text_ids"]);
    let prompt = model.prepare_text_tokens(&text_ids);
    let seed = traces["sampled_seed"].as_u64().unwrap();
    let mut keys = rng::KeySequence::new(seed);
    let ids = model
        .t3
        .inference_turbo(&cond, &prompt, &turbo_t3_params(0.8), &mut keys)
        .unwrap();
    let expected = i32_vec(&traces["sampled_ids"]);
    assert_eq!(ids, expected, "sampled id stream diverged");

    // The full recorded stream carries a trailing stop token when the
    // loop hit it before the reference popped it.
    let full = i32_vec(&traces["sampled_ids_full"]);
    let stop = model.config.t3.stop_speech_token;

    // Per-step replay of the whole filter chain from the recorded head
    // calls: penalty, temperature, top-k, top-p, then the categorical
    // draw from the same threefry seed.
    let (_, head_calls) = read_npy(&testdata("t3/sampled_head_calls.npy"));
    let steps = full.len();
    let vocab = head_calls.len() / steps;
    let margins = traces["sampled_margins"].as_array().unwrap();
    let mut keys = rng::KeySequence::new(seed);
    for step in 0..steps {
        let call = &head_calls[step * vocab..(step + 1) * vocab];
        let mut filtered = call.to_vec();
        let context: Vec<i32> = full[..step].to_vec();
        apply_repetition_penalty(&mut filtered, &context, 1.2);
        for v in &mut filtered {
            *v /= 0.8;
        }
        apply_top_k_threshold(&mut filtered, 1000);
        apply_top_p_shift(&mut filtered, 0.95);
        let picked = rng::categorical(&filtered, keys.next());
        assert_eq!(
            picked, full[step] as usize,
            "categorical replay diverged at step {step}"
        );
        // The post-penalty decision margin.
        let mut penalized = call.to_vec();
        apply_repetition_penalty(&mut penalized, &context, 1.2);
        let mut sorted = penalized.clone();
        sorted.sort_by(|a, b| b.partial_cmp(a).unwrap());
        let diff = (sorted[0] - sorted[1] - margins[step].as_f64().unwrap() as f32).abs();
        assert!(diff < 1e-4, "sampled margin {diff} at step {step}");
        assert!(full[step] != stop || step == steps - 1);
    }
}

#[test]
fn flow_decode_matches_reference() {
    let traces = read_json(&testdata("flow/traces.json"));
    let mut model = open_model();
    let inputs = flow_inputs();
    let mut keys = rng::KeySequence::new(0);
    let mel = model
        .s3gen
        .infer(
            &inputs.gen_tokens,
            &inputs.prompt_tokens,
            &inputs.prompt_feat,
            &inputs.embedding,
            traces["n_timesteps"].as_u64().unwrap() as usize,
            Some(&flow_noise(&inputs)),
            &mut keys,
        )
        .unwrap();
    let expected = inputs.flow_mel;
    let diff = max_diff(&mel, &expected);
    assert!(diff < 1e-4, "flow mel difference {diff}");
    // The shapes line up: 2 mel frames per generated token.
    assert_eq!(mel.len(), inputs.gen_tokens.len() * 2 * 80);
}

#[test]
fn hift_decode_matches_reference() {
    let traces = read_json(&testdata("hift/traces.json"));
    let model = open_model();
    let (_, mel_rows) = read_npy(&testdata("flow/flow_mel.npy"));
    let (_, phase) = read_npy(&testdata("hift/phase.npy"));
    let (_, sine_noise) = read_npy(&testdata("hift/sine_noise.npy"));
    let (_, source_noise) = read_npy(&testdata("hift/source_noise.npy"));
    let (_, expected_f0) = read_npy(&testdata("hift/f0.npy"));
    let (_, expected_wav) = read_npy(&testdata("hift/wav.npy"));

    // F0 through the ELU conv stack (the frames arrive transposed to
    // rows of 80).
    let mel_frames = traces["mel_frames"].as_u64().unwrap() as usize;
    let mut feat = vec![0.0f32; mel_frames * 80];
    for (i, &v) in mel_rows.iter().enumerate() {
        let frame = i / 80;
        let bin = i % 80;
        feat[frame * 80 + bin] = v;
    }
    let f0 = model.hift.predict_f0(&feat).unwrap();
    let diff = max_diff(&f0, &expected_f0);
    assert!(diff < 2e-3, "f0 difference {diff}");

    let draws = SineDraws {
        phase,
        sine_noise,
        source_noise,
    };
    let wav = model.hift.infer(&feat, Some(&draws)).unwrap();
    let diff = max_diff(&wav, &expected_wav);
    assert!(diff < 2e-4, "waveform difference {diff}");
}

#[test]
fn end_to_end_generate_matches_reference() {
    let traces = read_json(&testdata("end_to_end/traces.json"));
    let mut model = open_model();
    let cond = {
        let t3_traces = read_json(&testdata("t3/traces.json"));
        t3_cond_from_traces(&t3_traces)
    };
    // The flow reference conditioning from the flow case.
    let inputs = flow_inputs();
    let conds = super::Conditionals {
        t3: cond,
        gen: super::GenCond {
            prompt_token: inputs.prompt_tokens.clone(),
            prompt_feat: inputs.prompt_feat.clone(),
            embedding: inputs.embedding.clone(),
        },
    };
    let (_, sine_noise) = read_npy(&testdata("end_to_end/sine_noise.npy"));
    let (_, source_noise) = read_npy(&testdata("end_to_end/source_noise.npy"));
    let phase = f32_vec(&traces["phase"]);
    let draws = SineDraws {
        phase,
        sine_noise,
        source_noise,
    };
    let (_, e2e_noised) = read_npy(&testdata("end_to_end/noised_mels.npy"));
    let (_, e2e_zprompt) = read_npy(&testdata("end_to_end/z_prompt.npy"));
    let flow_noise = FlowNoise {
        gen_window: e2e_noised,
        prompt_window: e2e_zprompt,
    };
    let params = GenerateParams {
        t3: turbo_t3_params(0.0),
        seed: 0,
    };
    let text_ids = i32_vec(&traces["text_ids"]);
    let generated = model
        .generate(&text_ids, &conds, &params, Some(&draws), Some(&flow_noise))
        .unwrap();
    assert_eq!(
        generated.ids,
        i32_vec(&traces["ids"]),
        "end-to-end id stream diverged"
    );
    // The crop: ids below the vocabulary bound plus the three-silence
    // tail.
    let expected_tokens = i32_vec(&traces["speech_tokens"]);
    assert_eq!(generated.speech_tokens, expected_tokens);
    let tail = &generated.speech_tokens[generated.speech_tokens.len() - 3..];
    assert_eq!(tail, &[S3GEN_SIL, S3GEN_SIL, S3GEN_SIL]);
    assert!(generated
        .speech_tokens
        .iter()
        .all(|&t| t < SPEECH_VOCAB_SIZE));
    let (_, expected_wav) = read_npy(&testdata("end_to_end/wav.npy"));
    let diff = max_diff(&generated.samples, &expected_wav);
    assert!(diff < 2e-4, "end-to-end waveform difference {diff}");
    assert_eq!(generated.sample_rate, 24000);
}

#[test]
fn campplus_fbank_and_embedding_match_reference() {
    let model = open_model();
    let (_, wave) = read_npy(&testdata("campplus/wave.npy"));
    let (_, expected_fbank) = read_npy(&testdata("campplus/fbank.npy"));
    let (_, expected_embedding) = read_npy(&testdata("campplus/embedding.npy"));

    // The float64 Kaldi fbank with the per-bin mean removal.
    let fbank = super::fbank::mean_normalized_fbank(&wave);
    let frames = fbank.len();
    let bins = fbank.first().map_or(0, Vec::len);
    let mut flat = Vec::with_capacity(frames * bins);
    for row in &fbank {
        flat.extend_from_slice(row);
    }
    assert_eq!(frames * bins, expected_fbank.len());
    let diff = max_diff(&flat, &expected_fbank);
    assert!(diff < 1e-4, "fbank difference {diff}");

    let embedding = model.s3gen.speaker_embed(&flat, frames);
    let diff = max_diff(&embedding, &expected_embedding);
    assert!(diff < 2e-4, "campplus embedding difference {diff}");
}

#[test]
fn sampling_traces_match_reference() {
    let traces = read_json(&testdata("sampling/traces.json"));
    for case in traces["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        match name {
            "repetition_penalty_duplicates" => {
                let mut logits = f32_vec(&case["logits"]);
                let context = i32_vec(&case["context"]);
                apply_repetition_penalty(
                    &mut logits,
                    &context,
                    case["penalty"].as_f64().unwrap() as f32,
                );
                let diff = max_diff(&logits, &f32_vec(&case["penalized"]));
                assert!(diff < 1e-6, "{name}: {diff}");
            }
            "temperature_divide" => {
                let scaled: Vec<f32> = f32_vec(&case["logits"])
                    .iter()
                    .map(|v| v / case["temperature"].as_f64().unwrap() as f32)
                    .collect();
                let diff = max_diff(&scaled, &f32_vec(&case["scaled"]));
                assert!(diff < 1e-6, "{name}: {diff}");
            }
            "top_k_threshold" | "top_k_all_kept" => {
                let mut filtered = f32_vec(&case["logits"]);
                apply_top_k_threshold(&mut filtered, case["top_k"].as_u64().unwrap() as usize);
                let diff = max_diff_infinite(&filtered, &f32_vec_masked(&case["filtered"]));
                assert!(diff == 0.0, "{name}: {diff}");
            }
            "top_p_shift_0_9" | "top_p_shift_0_5" => {
                let mut filtered = f32_vec(&case["logits"]);
                apply_top_p_shift(&mut filtered, case["top_p"].as_f64().unwrap() as f32);
                let diff = max_diff_infinite(&filtered, &f32_vec_masked(&case["filtered"]));
                assert!(diff == 0.0, "{name}: {diff}");
            }
            "filtered_categorical" => {
                let logits = f32_vec_masked(&case["logits"]);
                let uniform = f32_vec(&case["uniform"])[0];
                let winner = categorical_with_uniform(&logits, uniform);
                assert_eq!(
                    winner,
                    case["winner"].as_u64().unwrap() as usize,
                    "{name} winner diverged"
                );
                let margin = case["prob_margin"].as_f64().unwrap();
                assert!(margin > 1e-4, "{name}: margin {margin}");
            }
            "greedy_argmax" => {
                let logits = f32_vec(&case["logits"]);
                let argmax = crate::tts::sampling::argmax(&logits);
                assert_eq!(argmax, case["argmax"].as_u64().unwrap() as usize);
            }
            other => panic!("unknown sampling case {other}"),
        }
    }
}

/// The inverse-CDF categorical draw with a given uniform (the fixture
/// records the reference's draw so the Rust math replays it without
/// consuming the crate RNG; the drawn loop path is pinned separately
/// by the sampled T3 replay).
fn categorical_with_uniform(logits: &[f32], uniform: f32) -> usize {
    let max = logits.iter().copied().fold(f32::NEG_INFINITY, f32::max);
    let weights: Vec<f64> = logits
        .iter()
        .map(|&x| (x - max) as f64)
        .map(|v| v.exp())
        .collect();
    let total: f64 = weights.iter().sum();
    let u = uniform as f64 * total;
    let mut cumulative = 0.0f64;
    let mut count = 0usize;
    for &w in &weights {
        if cumulative > u {
            break;
        }
        count += 1;
        cumulative += w;
    }
    count.saturating_sub(1).min(weights.len() - 1)
}

/// Max diff that treats -inf == -inf as equal (the filtered vectors).
fn max_diff_infinite(a: &[f32], b: &[f32]) -> f32 {
    assert_eq!(a.len(), b.len());
    let mut worst = 0.0f32;
    for (x, y) in a.iter().zip(b) {
        if x.is_infinite() && y.is_infinite() {
            continue;
        }
        worst = worst.max((x - y).abs());
    }
    worst
}

#[test]
fn punc_norm_matches_the_turbo_table() {
    // Empty text falls back to the fixed sentence.
    assert_eq!(punc_norm(""), "You need to add some text for me to talk.");
    // The first letter is capitalized.
    assert_eq!(punc_norm("hello there"), "Hello there.");
    // Whitespace runs collapse.
    assert_eq!(punc_norm("a  b\n c"), "A b c.");
    // The turbo replacement table: no three-dot or spaced-dash rules.
    assert_eq!(punc_norm("wait\u{2026} ok"), "Wait,  ok.");
    assert_eq!(punc_norm("a: b"), "A, b.");
    assert_eq!(punc_norm("a \u{2014} b"), "A - b.");
    assert_eq!(punc_norm("a \u{2013} b"), "A - b.");
    assert_eq!(punc_norm("\u{201c}hi\u{201d}"), "\"hi\".");
    assert_eq!(punc_norm("it\u{2019}s"), "It's.");
    // Sentence enders are ASCII only; a trailing space is trimmed.
    assert_eq!(punc_norm("really? "), "Really?");
    assert_eq!(punc_norm("no, "), "No,");
    assert_eq!(punc_norm("stop-"), "Stop-");
}
